#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public SPROLOZ  {  int nType;  int nValue;  //  } Queue_KvoSH;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintKvoSH(DefinePaint)  {  QueueP(Queue_KvoSH);  //  CMyPen re( hDC, 0x80ff );  re.Rect( p->mRect );    double dValue = 0;  CShKVO* sh=NULL;  if (p->nNumber!=-1)	sh = (CShKVO*)PipeSh;  else  if (p->nSocketNumber!=-1)	sh=(CShKVO*)q.m_pSocket->Sh(p->nSocketNumber);  //  if (sh==NULL)	  return 1;  //  if ( !(IsTypeOk) ) return 1;  //  switch ( p->nValue )    {    case  0: // Показывает положение амперметра      dValue = ( sh->Eq_State( CKVO::On ) ) ? 1.0 : 0.0;    break;    case  1:dValue = sh->VentDrainIn ;break;    case  2:dValue = sh->VentDrainOut;break;    };  //  if ( p->nType == 0 ) DrawValue( hDC, p, dValue, "%" );  else  if ( p->nType == 1 )    {    if ( dValue <= 0. ) return 1;    CKVO::eTypeDrain drain;    switch ( p->nValue )      {      case  1:drain = sh->TypeDrainIn ;break;      case  2:drain = sh->TypeDrainOut;break;      default: return 1;      }    //    int Index = -1;	  switch( drain )	    {      case CKVO::DRAIN_LIQ :Index = 2;break;      case CKVO::DRAIN_GAS :Index = 1;break;      case CKVO::DRAIN_NO  :      default: return 1;	    };    static TCHAR* text[] =       {	    "Идет Х.З."    ,	    "Идет газ"     ,	    "Идет жидкость",      };    ::DrawText( hDC, text[Index], lstrlen(text[Index]), &p->mRect,      DT_CENTER | DT_VCENTER | DT_SINGLELINE );    //    }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~extern int nLastKVO;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddKvoSH(DefineTegs)  {  //  AddQueueEx(Queue_KvoSH);  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintKvoSH;  p->nValue = nLastKVO;  p->nSocketNumber=-1;  p->nNumber=-1;  //  STegObj obj[] =    {    { 'I', "type" , &p->nType },    // Дополнительная информация    EXT_QUEUE    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  AddPRSH( def, id_KVO, teg[0].value, p, p->nValue );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~